    EXPECT_EQ(analysis.topologicalOrder()[1u], stream);
    EXPECT_EQ(analysis.topologicalOrder()[2u], clear);
    EXPECT_EQ(analysis.topologicalOrder()[3u], dispatchA);
    EXPECT_EQ(analysis.topologicalOrder()[4u], rasterA);
